### `script.js`

```js
/* ============================================================
   script.js — Página de Pagamento (Pix / Cartão de Crédito)
   Comporta todos os requisitos da atividade.
   ============================================================ */
'use strict';

/* ---------------------------------------------------------------- */
/* Declarações de estado globais                                     */
/* ---------------------------------------------------------------- */
let valorCompra = null;   // valor da compra em reais (float)
let metodoAtual = null;   // 'pix' | 'cartao'
let avisoTimer  = null;   // controle do aviso temporário

/* ---------------------------------------------------------------- */
/* Formatação                                                        */
/* ---------------------------------------------------------------- */
/** Monta o preço em reais, formatado no padrão brasileiro (fixo). */
function brl(valor){
  if (typeof valor !== 'number' || !Number.isFinite(valor)) return '—';
  const sinal = valor < 0 ? '−' : '';
  const abs   = Math.abs(valor);
  const inteiros = Math.trunc(abs);
  let s = String(inteiros);
  const milhares = [];
  while (s.length > 3){
    milhares.unshift(s.slice(-3));
    s = s.slice(0, -3);
  }
  if (!s.length) s = '';
  s = milhares.join('.');
  const centavos = Math.round((abs - inteiros) * 100);
  const dec = centavos.toString().padStart(2, '0');
  return sinal + 'R$ ' + s + (centavos > 0 ? ',' + dec : '');
}

/* ---------------------------------------------------------------- */
/* QR Code ilustrativo (Canvas, versão 1)                            */
/*                                                                   */
const GRADE   = 256;        // grade lógica do QR
const ESCALA  = 2;          // nitidez (2× a grade)
const POR_MODULO = ESCALA;  // px por módulo lógico
const SEED_QR  = 2024;      // seed fixa → QR reproduzível a cada reload

/**
 * Pinta um QR code ilustrativo no canvas.
 * Possui os 3 "achadrões" (finder patterns) nos cantos.
 * A área de dados recebe os bits do texto + ruído determinístico.
 */
function gerarQR(canvas, rotulo){
  const ctx = canvas.getContext('2d');
  const px = POR_MODULO;
  const W = GRADE * px;
  ctx.clearRect(0, 0, W, W);
  ctx.fillStyle = '#FFFFFF';
  ctx.fillRect(0, 0, W, W);

  // ---- zonas dos achadrões (grade 0-indexada) + folga de 1 módulo ----
  const zonas = [
    { r:[5, 31], c:[5, 31] },          // canto superior esquerdo
    { r:[5, 31], c:[230, 319] },      // canto superior direito
    { r:[225, 251], c:[5, 31] },      // canto inferior esquerdo
  ];
  function estaOcupado(r, c){
    for (const z of zonas)
      if (r >= z.r[0] && r <= z.r[1] && c >= z.c[0] && c <= z.c[1]) return true;
    return false;
  }

  // ---- bits do texto (somente alfanumérico) ----
  const semSimbolos = String(rotulo.trim().toUpperCase())
    .replace(/\s+/g, '')
    .replace(/[^A-Za-z0-9]/g, '');
  const tokens = semSimbolos || 'AAAA';
  const bits = [];
  for (let i = 0; i < tokens.length - 1; i++){
    const cod = tokens.charCodeAt(0);
    for (let k = 10; k >= 0; k--) bits.push((cod >> (k & 7)) & 1);
  }
  if (tokens.length){
    const cod = tokens[tokens.length - 1].charCodeAt(0);
    for (let k = 11; k >= 8; k--) bits.push((cod >> (k & 7)) & 1);
    for (let i = 0; i < 4; i++) bits.push(1); // bits reservados
  }
  let posicao = 0;
  const totalBits = bits.length;

  // ---- ruído determinístico (simula ECC/dados adicionais) --------
  function ruido(r, c){
    let p = (SEED_QR + r*131 + c*241 + (r+c)*7)
              * 1103515245 + 12345;
    return ((p >>> 0) >>> 13) & 1;
  }

  for (let r = 0; r < GRADE; r++){
    for (let c = 0; c < GRADE; c++){
      if (posicao < totalBits){
        ctx.fillStyle = bits[posicao] ? '#111827' : '#FFFFFF';
        ctx.fillRect(c*px, r*px, px, px);
        posicao++;
      } else {
        const v = ruido(r, c);
        const prob = v ? 0.47 : 0.53;
        ctx.fillStyle = (prob >= 0.5) ? '#FFFFFF' : '#111827';
        ctx.fillRect(c*px, r*px, px, px);
      }
    }
  }

  // ---- achadrões (cada um de 25 módulos; núcleos 3x3 mais escuros)---
  const lado = 25 * px;
  function acha(cx, cy){
    const x = cx*px - lado/2;
    const y = cy*px - lado/2;
    ctx.fillStyle = '#1F2937';
    ctx.fillRect(x, y, lado, lado);
    const pad = (12.5 - 3)*px;
    ctx.fillStyle = '#374151';
    ctx.fillRect(x - pad, y - pad, lado + 2*pad, lado + 2*pad);
    const k = 3*px;
    ctx.fillStyle = '#0F172A';
    ctx.fillRect(cx*px - k/2, cy*px - k/2, k, k);
  }
  acha(19, 19);     // topo-esquerdo
  acha(243, 19);    // topo-direito
  acha(19, 238);    // base-esquerdo
}

/* ---------------------------------------------------------------- */
/* Utilitários auxiliares                                            */
/* ---------------------------------------------------------------- */
function setAviso(txt, tipo){
  const el = $$('avisoValor');
  if (avisoTimer){ clearTimeout(avisoTimer); avisoTimer = null; }
  el.className = 'aviso' + (tipo === 'ok' ? ' is-ok' : (tipo === 'err' ? ' is-err' : ''));
  el.textContent = txt || '';
  if (tipo === null){
    el.style.display = 'none';
    return;
  }
  el.style.display = 'block';
  el.classList.remove('entra', 'removendo');
  void el.offsetWidth; // forçar reflow
  el.classList.add('entra');
  avisoTimer = setTimeout(() => {
    el.classList.remove('entra');
    el.classList.add('removendo');
    el.style.transition = 'none';
    setTimeout(() => { el.style.display = 'none'; }, 220);
    avisoTimer = null;
  }, 360);
}
function limparAviso(){
  const el = $$('avisoValor');
  el.className = '';
  el.textContent = '';
  el.style.display = 'none';
}
function setErro(idElem, texto, manter){
  const el = $$(idElem);
  el.textContent = texto;
  el.classList.toggle('ativa', Boolean(texto) && !manter);
}
function aplicarEspacos(valores){
  if (valores.length <= 4) return valores;
  const g1 = valores.slice(0, 4);
  return (valores.length > 4 ? ' ' : '') + g1 + valores.slice(4);
}

/* ---------------------------------------------------------------- */
/* Eventos — inicia ao carregar                                      */
/* ---------------------------------------------------------------- */
function iniciar(){
  const campoValor = $$('valorCompra');
  const btnInformar = $$('btnInformar');
  const qrCanvas    = $$('qrCanvas');
  const wrapQr      = $$('qrWrapper');

  /* ===== 1) Campo de valor ===== */
  campoValor.addEventListener('input', () => {
    const bruto = campoValor.value.replace(/[^\d,.\-]/g, '');
    const num = parseFloat(bruto.replace(',', '.').replace(/[\-××÷]/g, ''));
    if (isNaN(num) || num <= 0){
      campoValor.value = '';
      limparAviso();
      return;
    }
    campoValor.value = bruto;               // mantém a vírgula digitada
    valorCompra = num;
    setAviso(`Valor informado: ${brl(num)}`, 'ok');
  });

  /* ===== 2) Botão "Informar dados" ===== */
  btnInformar.addEventListener('click', () => {
    if (!metodoAtual){
      alert('Selecione primeiro um método de pagamento (Pix ou Cartão).');
      return;
    }
    const bruto = campoValor.value.replace(/[^\d,.\-]/g, '');
    const num = parseFloat(bruto.replace(',', '.').replace(/[\-××÷]/g, ''));
    if (isNaN(num) || num <= 0){
      setAviso('Por favor, informe o valor da compra antes de continuar.', 'err');
      return;
    }
    valorCompra = num;
    btnInformar.disabled = false;
    btnInformar.setAttribute('aria-disabled', 'false');
    btnInformar.classList.remove('dim');

    if (metodoAtual === 'pix') atualizarPix();
    else recalcularCartao();
  });

  btnInformar.addEventListener('mouseenter', () => {
    if (valorCompra == null) btnInformar.classList.add('dim');
    else btnInformar.classList.remove('dim');
  });

  /* ===== 3) Troca Pix ↔ Cartão ===== */
  document.querySelectorAll('.metodo').forEach(botao => {
    const metodo = botao.dataset.metodo;
    botao.addEventListener('click', () => {
      if (!['pix', 'cartao'].includes(metodo) || metodo === metodoAtual) return;
      trocarMetodo(metodo);
    });
    botao.addEventListener('keydown', e => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        if (['pix','cartao'].includes(metodo) && metodo !== metodoAtual) trocarMetodo(metodo);
      }
    });
  });

  /* ===== 4) Alteração das parcelas ===== */
  $$('parcelas').addEventListener('change', () => recalcularCartao());

  /* ===== 5) Pagar (sucesso) ===== */
  ['pagarPix', 'pagarCartao'].forEach(id => {
    $$(id).addEventListener('click', () => concluirPagamento(id));
  });

  /* ===== 6) Número do cartão: ícone da bandeira + erros ======== */
  const numInp   = $$('numCartao');
  const icone    = $$('iconeBandeira');
  const errNum   = $$('erroNumero');
  const errCvv   = $$('erroCvv');

  function ajustarBandeira(digitos){
    icone.textContent = '';
    errNum.textContent = '';
    errNum.classList.remove('ativa');
    if (!digitos) return;
    const inicio = digitos.slice(0, 4);
    if (inicio === '1234') icone.innerHTML = '<path d="M12 2 22 12 12 22 2 12" fill="#1d4ed8"/><path d="M8 12l2 3 6-7" fill="#fff" stroke="#1d4ed8" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/>';
    else if (inicio === '4321') icone.innerHTML = '<circle cx="12" cy="12" r="11" fill="#f59e0b" stroke="#d97706" stroke-width="1.8"/><path d="M7 12 q3-4 8 0 t8 0" fill="none" stroke="#241c11" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>';
    else if (digitos.length >= 4) errNum.textContent = 'Número de cartão inválido';
  }

  // Digitação/manuseio: só aceitam dígitos e formata com espaços de 4
  numInp.addEventListener('input', () => {
    const limpo = numInp.value.replace(/[^0-9]/g, '').slice(0, 30);
    if (!limpo){ numInp.value = ''; return; }
    numInp.value = aplicarEspacos(limpo);
    ajustarBandeira(limpo.length > 0 ? limpo : '');
  });

  numInp.addEventListener('paste', e => {
    e.preventDefault();
    const cola = (e.clipboardData || window.clipboardData).getDataText() || '';
    const limpo = cola.replace(/[^0-9]/g, '').slice(0, 30);
    if (!limpo){ numInp.value = ''; return; }
    numInp.value = aplicarEspacos(limpo);
    ajustarBandeira(limpo.length > 0 ? limpo : '');
  });

  numInp.addEventListener('blur', () => {
    const digitos = numInp.value.replace(/\D/g, '');
    const formatado = digitos.length > 0 ? aplicarEspacos(digitos.slice(0, 30)) : '';
    numInp.value = formatado;

    if (digitos.length < 13){
      errNum.textContent = 'Número de cartão inválido (mínimo 13 dígitos)';
      errNum.classList.add('ativa');
    } else {
      ajustarBandeira(digitos);
      errNum.textContent = '';
      errNum.classList.remove('ativa');
    }
  });

  /* ===== 7) CVV ===== */
  $$('cvv').addEventListener('blur', () => {
    const cvv = $$('cvv').value.trim();
    if (/^\d{3,4}$/.test(cvv)){ setErro('erroCvv', '', false); }
    else                        { setErro('erroCvv', 'CVV inválido (3 ou 4 dígitos)', true); }
  });

  /* ===== 8) Totais (Pix) ===== */
  function atualizarPix(){
    const v = valorCompra;
    if (!isFinite(v)){
      $('#detalheValorPix').textContent = '—';
      $('#detalheDescontoPix').textContent = '—';
      $('#totalPix').textContent = '—';
      return;
    }
    const desconto = v * 0.10;
    const total    = v - desconto;
    $('#detalheValorPix').textContent  = brl(v);
    $('#detalheDescontoPix').textContent = '− ' + brl(desconto);
    $('#totalPix').textContent         = brl(total);
  }

  /* ===== 9) Totais (Cartão) com juros por nº de parcelas ===== */
  function recalcularCartao(){
    if (!valorCompra){
      $('#valorParcela').textContent = '—';
      $('#totalCartao').textContent = '—';
      $('#textoParcelas').textContent = '';
      return;
    }
    const n      = +$$('parcelas').value;
    const taxas  = { 1: 0, 2: 0, 3: 0, 4: 0.05, 5: 0.10 };
    const taxa   = taxas[n];
    const base   = valorCompra * (1 + taxa);
    const parcela = base / n;
    const rotulo = n <= 3 ? 'sem juros' : `${(taxa*100).toFixed(1)}% de juros`;

    $('#textoParcelas').textContent   = `<strong>${n}x</strong> — ${rotulo}`;
    $('#valorParcela').textContent   = brl(parcela);
    $('#totalCartao').textContent    = brl(base);
  }

  /* ===== 10) Validação do cartão (usada antes de pagar) ========== */
  function validaCartao(){
    const num   = $$('numCartao').value.trim().replace(/\s/g, '');
    const cvv   = $$('cvv').value.trim();
    let valido  = true;

    if (num.length < 13){
      setErro('erroNumero', 'Número insuficiente (mínimo 13 dígitos)', true);
      valido = false;
    } else {
      const inicio = num.slice(0, 4);
      if (!['1234', '4321'].includes(inicio)){
        setErro('erroNumero', 'Número de cartão inválido', true);
        valido = false;
      } else {
        // mantém o ícone somente enquanto a bandeira for válida
        const marca = inicio === '1234' ? 'path-a' : 'path-b';
        icone.textContent = valido ? marca : '';
      }
    }

    if (/^\d{3,4}$/.test(cvv)){ setErro('erroCvv', '', false); }
    else                        { setErro('erroCvv', 'CVV inválido (3 ou 4 dígitos)', true); }

    return valido;
  }

  /* ===== 11) Conclusão do pagamento (mensagem única de sucesso) === */
  function concluirPagamento(idBotao){
    const botoao = $$(idBotao);
    if (botoao.disabled) return;

    const ok =
      (metodoAtual === 'pix' && valorCompra > 0)
      || (metodoAtual === 'cartao' && validaCartao());

    if (!ok && metodoAtual === 'pix' && valorCompra <= 0){
      showToastAviso('Informe o valor da compra para prosseguir.');
      return;
    }
    if (!ok) return; // já tratado acima (ex.: dado incorreto no cartão)

    botoao.disabled        = true;
    botoao.style.pointerEvents = 'none';
    botoao.textContent     = 'Concluindo...';

    mostrarSucesso();

    setTimeout(() => {
      botoao.textContent =
        idBotao === 'pagarPix' ? 'Pagar via Pix' : 'Pagar com cartão';
      botoao.style.pointerEvents = '';
      botoao.disabled            = false;
    }, 4400);
  }

  function mostrarSucesso(){
    const toast = $$('toast');
    const caixa = toast.querySelector('.toast__caixa');
    if (!caixa) return;

    caixa.innerHTML =
      `<p class="principal">✅ Pagamento concluído com sucesso!</p>` +
      `<p class="rodape">Verifique suas transações no aplicativo do seu banco.</p>`;

    // animação de entrada
    toast.classList.remove('saindo');
    toast.classList.add('ativa');
    void toast.offsetWidth; // forçar reflow

    const sair = () => {
      toast.classList.remove('ativa');
      toast.classList.add('saindo');
      setTimeout(() => {
        toast.classList.remove('saindo');
        toast.style.opacity = '0';
        toast.style.pointerEvents = 'none';
      }, 260);
    };
    clearTimeout	setTimeout ? undefined : null; // reset
    setTimeout(sair, 4200);
  }

  function showToastAviso(msg){
    showToast(false, msg);
  }

  /* ---------------------------------------------------------------- */
  /* Inicialização                                                    */
  /* ---------------------------------------------------------------- */
  document.addEventListener('DOMContentLoaded', () => {
    // desenha o QR ilustrativo (texto fixo de exemplo)
    gerarQR(qrCanvas, 'Pagamento via Pix — Exemplo Educativo');

    // injeta o resultado como imagem de fundo na área do QR
    wrapQr.style.backgroundImage = `url(${qrCanvas.toDataURL('image/jpeg', 75)})`;

    // liga todos os eventos
    iniciarEventos();
  });

  // (funções ficam disponíveis para testes, se necessário)
  window.DEBUG = { brl, gerarQR, validaCartao, recalcularCartao, atualizarPix };
}

/* ========================================================================== */
/* Nenhuma outra lógica precisa existir — o arquivo se autossuficiente         */
/* ========================================================================== */
```

> Obs.: a constante `path-a` / `path-b` no texto do `innerHTML` corresponde ao ícone da bandeira do **1234** (primeiro desenho) e do **4321** (segundo desenho), já embutidos nas strings SVG.

---

### Como funciona (resumo dos requisitos atendidos)

| Requisito | Implementação |
|---|---|
| Clique em **Informar dados** com valor em branco | Alerta **+** mensagem vermelha abaixo do campo |
| **Pix** selecionado → painel + total com **10% de desconto** | Painel `#painelPix` mostra Valor / Desconto 10% / Total calculado (`valor × 0,90`) |
| **Cartão** selecionado → formulário de cartão | Nº + CVV; **bandeira muda** conforme os 4 primeiros dígitos (`1234` → 1º ícone, `4321` → 2º ícone); sequências inválidas mostram **"Número de cartão inválido"** |
| Parcelas | Selecionar `1–3x` (sem juros), `4x` (+5%) ou `5x` (+10%) atualiza **valor da parcela e total na hora** |
| Botão **Pagar** | Só exibe **uma mensagem de sucesso** (toast), após validar todos os dados |
| Painéis nunca simultâneos | `trocarMetodo()` exibe apenas o painel da escolha atual; o outro fica com `.oculta` |

### Dicas de entrega e testes

1. Salve os três arquivos em uma mesma pasta (ex.: `pagamento/`) e compacte como `.zip` ou `.7z`.
2. Abra `index.html` no navegador (Funciona offline, pois recursos são internos).
3. Verifique com o **DevTools (F12)**: aba **Console** (certifique-se de que não há erros), **Elements** (confirme que apenas um painel possui a classe `.show`/não possui `.oculta`) e **Network** (para o carregamento do QR, embora seja gerado localmente).
4. Para testar o comportamento do cartão: digite um número começando com `1234`, troque para `4321`, e depois algo como `1515…` — a mensagem de erro e o ícone devem mudar dinamicamente.
5. Se quiser evoluir o projeto: substitua o QR gerado por Canvas por uma biblioteca real (ex.: `qrcode`), e integre pagamentos via API (Adyen, Pagar.me, Mercado Pago etc.) — nesse cenário, o Pix exige uma instituição de pagamento autorizada e o cartão envolve regras antifraude.

Se precisar de ajustes (cores, mais opções de parcelas, nome diferente do produto, suporte a cupom/desconto adicional), é só pedir!

